        \u73B0\u503C: '\u6821\u52D8.\u5DF2\u6838["\u4E01/\u5BC5"].\u539F\u6587 = \u300C\u975E\u5E9A\u4E0D\u80FD\u5288\u7532,\u975E\u7532\u4E0D\u80FD\u5F15\u4E01\u300D,\u51FA\u5904\u6807\u300A\u7A77\u901A\u5B9D\u9274\u300B\u4E01\u706B\u7BC7',
        \u7591\u70B9: "\u8BE5\u5341\u4E8C\u5B57\u5728\u77E5\u781A\u658B\u672C\u3010\u6B63\u6708\u4E01\u706B\u3011\u6761\u91CC\u4E0D\u662F\u539F\u6837(\u6B63\u6708\u4F5C\u300C\u975E\u5E9A\u4E0D\u80FD\u5288\u7532,\u4F55\u4EE5\u5F15\u4E01,\u59D1\u7528\u5E9A\u91D1\u300D);\u4E0E\u5B83\u6700\u63A5\u8FD1\u7684\u662F\u5F71\u5370\u672C\u3010\u4E09\u51AC\u4E01\u706B\u603B\u7EB2\u3011\u300C\u7121\u5E9A\u4E0D\u80FD\u5288\u7532,\u7121\u7532\u4F55\u4EE5\u5F15\u4E01\u300D",
        \u5224\u636E: "qtbj.txt 594~853 \u884C\u5168\u6587\u68C0\u7D22 + \u5F71\u5370\u672C \u4E09\u51AC\u4E01\u706B\u7E3D\u8AD6 \u89C6\u89C9\u6838\u5BF9(M2 \u4E01\u884C)",
