          \u540D: "\u56F0\u4E19",
          \u82E5: "\u900F\u6570:\u4E19=1 \u4E14 \u6709\u6570:\u7678>=2",
          \u5219: "\u6216\u4E19\u5C11\u7678\u591A\uFF0C\u53C8\u4E3A\u56F0\u4E19\uFF0C\u7EC8\u4E3A\u5BD2\u58EB",
          \u6863: "\u4E0B",
          \u610F\u8C61: "\u4E00\u70B9\u9633\u88AB\u6C34\u5C42\u5C42\u88F9\u4F4F\uFF0C\u5149\u900F\u4E0D\u51FA"
