          \u9020\u5316\u5143\u94A5\u7CFB: "\u4E19\u7532\u5169\u900F\uFF0C\u7678\u6C34\u6703\u5C40\u85CF\u8FB0\uFF0C\u65AF\u6587\u9818\u8896\uFF0C\u601D\u616E\u660E\u901A\uFF0C\u5373\u98A8\u571F\u4E0D\u53CA\uFF0C\u4EA6\u4E0D\u5931\u5BCC\u8CB4\uFF0C\u5A01\u93AE\u4E09\u908A",
          \u8BF4\u660E: "\u2460\u300C\u4E19\u7533\u300D\u2192\u300C\u4E19\u7532\u300D,\u5F71\u5370\u672C\u5750\u5B9E\u4E3A\u7535\u5B50\u672C\u8BB9\u5B57,\u672C\u8868 \u82E5 \u5DF2\u6309\u300C\u4E19\u7532\u4E24\u900F\u300D\u5224;\u2461\u5F71\u5370\u672C\u65AD\u8BED\u8FDC\u8F83\u77E5\u781A\u658B\u8BE6(\u65AF\u6587\u9818\u8896\u3001\u601D\u616E\u660E\u901A\u3001\u5A01\u93AE\u4E09\u908A),\u77E5\u781A\u658B\u53EA\u7559\u300C\u4EA6\u4E0D\u5931\u5BCC\u8D35\u300D\u3002"
