      \u7EA7\u522B: "\u4F50\u8BC1",
      \u51FA\u5904: "\u300A\u7A77\u901A\u5B9D\u9274\u300B\u8BB8\u660C\u77E5\u781A\u658B\u6574\u7406\u672C(\u7D20\u6750/\u7A77\u901A\u5B9D\u9274.pdf) \u8BBA\u7678\u6C34 \u6B63\u6708/\u4E8C\u6708/\u4E09\u6708/\u56DB\u6708/\u4E94\u6708/\u516D\u6708/\u4E03\u6708/\u516B\u6708/\u4E5D\u6708/\u5341\u6708/\u5341\u4E00\u6708/\u5341\u4E8C\u6708(\u6253\u5E95) + \u300A\u9020\u5316\u5143\u94A5\u8BC4\u6CE8\u300B\u674E\u94C1\u7B14\u5F71\u5370\u672C(\u7D20\u6750/xzb2100653) \u4E66\u9875420/421(\u5F71\u5370\u62BD\u67E5\xB7\u2696 \u5206\u6B67)",
      \u539F\u6587: "\u6B63\u6708\u7678\u6C34\uFF0C\u503C\u4E09\u9633\u4E4B\u5F8C\uFF0C\u96E8\u9732\u4E4B\u7CBE\uFF0C\u5176\u6027\u81F3\u67D4\uFF0C\u5148\u7528\u8F9B\u91D1\uFF0C\u751F\u7678\u6C34\u4E4B\u6E90\uFF0C\u6B21\u7528\u4E19\u706B\u7167\u6696\uFF0C\u540D\u9634\u9633\u548C\u5408\uFF0C\u4E07\u7269\u53D1\u751F\uFF0C\u8F9B\u4E19\u4E24\u900F\uFF0C\u91D1\u699C\u6709\u540D\u3002\u6216\u652F\u6210\u706B\u5C40\uFF0C\u8F9B\u91D1\u53D7\u4F24\uFF0C\u6709\u58EC\u51FA\u6551\u8005\uFF0C\u5BCC\u8D35\uFF0C\u65E0\u58EC\u8005\uFF0C\u8D2B\u7A77\uFF0C\u6216\u4E19\u51FA\u5929\u5E72\uFF0C\u8F9B\u5728\u9149\u4E11\uFF0C\u4EA6\u6709\u8863\u887F\uFF0C\u82E5\u8F9B\u4E19\u7686\u65E0\uFF0C\u8D2B\u5BD2\u4E0B\u683C\uFF0C\u6216\u8F9B\u900F\u4E19\u85CF\uFF0C\u6069\u8363\u4E4B\u9020\uFF0C\u4E19\u8F9B\u5728\u67F1\uFF0C\u4EE5\u5BCC\u5F97\u5B98\u3002\u6216\u620A\u900F\u6708\u4E0A\uFF0C\u5750\u8FB0\u65F6\uFF0C\u4E0D\u89C1\u6BD4\u52AB\uFF0C\u4E19\u4E01\u51FA\u5E72\uFF0C\u6B64\u4E3A\u5316\u5408\uFF0C\u5B9A\u4E3B\u8170\u91D1\uFF0C\u89C1\u5211\u51B2\uFF0C\u5219\u5426\u3002\u6216\u652F\u6210\u6C34\u5C40\uFF0C\u5B9C\u6709\u4E19\u900F\uFF0C\u65E0\u58EC\u8005\uFF0C\u8863\u7984\u4E0D\u5C11\uFF0C\u82E5\u89C1\u4E19\u706B\u91CD\u91CD\uFF0C\u53C8\u4F5C\u8D35\u63A8\u3002\u6B63\u6708\u7678\u6C34\uFF0C\u8F9B\u91D1\u4E3A\u4E3B\uFF0C\u5E9A\u91D1\u6B21\u4E4B\uFF0C\u4E19\u4EA6\u53EF\u5C11\uFF0C\u82E5\u65E0\u5E9A\u8F9B\uFF0C\u867D\u6709\u4E19\u706B\uFF0C\u65E0\u7528\u4E4B\u4EBA\uFF0C\u6216\u706B\u591A\u571F\u591A\uFF0C\u6B8B\u75BE\u4E0D\u514D\u3002\u7528\u8F9B\u8005\uFF0C\u571F\u59BB\u91D1\u5B50\u3002",
      \u5F71\u5370\u672C\u62BD\u67E5: {
        \u4E66\u9875: "420/421(PDF 212)",
        \u7ED3\u8BBA: "\u2696 \u5206\u6B67",
        \u8BB0\u5F55: "\u7B2C\u56DB\u5341\u4E09\u7BC0 \u4E09\u6625\u7678\u6C34\u7E3D\u8AD6\u3010\u539F\u6587\u3011\u4F5C\u300C\u6B63\u6708\u7678\u6C34\uFF0C\u503C\u4E09\u967D\u4E4B\u5019\uFF0C\u70BA\u96E8\u9732\u4E4B\u7CBE\uFF0C\u96E8\u9732\u4E4B\u6027\u81F3\u5F31\uFF0C\u5C08\u53D6\u8F9B\u91D1\u767C\u6E90\uFF0C\u6B21\u53D6\u4E19\u706B\u7167\u6696\uFF0C\u540D\u9670\u967D\u548C\u5408\uFF0C\u842C\u7269\u767C\u751F\u3002\u5F97\u4E19\u8F9B\u5169\u900F\uFF0C\u79D1\u7532\u5BCC\u8CB4\u975E\u5E38\uFF0C\u84CB\u7678\u70BA\u96E8\u9732\uFF0C\u80FD\u6210\u4EA5\u5B50\u6C5F\u6CB3\u4E5F\u3002\uFF0F\u6216\u652F\u6210\u706B\u5C40\uFF0C\u8F9B\u91D1\u53D7\u56F0\uFF0C\u6709\u58EC\u5BCC\u8CB4\uFF0C\u7121\u58EC\u8CA7\u8CE4\uFF0C\u6216\u4E19\u900F\u5929\u5E72\uFF0C\u8F9B\u85CF\u9149\u4E11\uFF0C\u4EA6\u4E3B\u8CA2\u76E3\u751F\u54E1\uFF0C\u8F9B\u4E19\u4FF1\u7121\uFF0C\u5B9A\u4E3B\u8CA7\u8CE4\uFF0C\u6216\u8F9B\u900F\u58EC\u85CF\uFF0C\u6069\u5C01\u986F\u8077\uFF0C\u4E19\u8F9B\u7686\u85CF\uFF0C\u5BCC\u4E2D\u53D6\u8CB4\u3002\u300D\u2460\u300C\u503C\u4E09\u967D\u4E4B\u5F8C\u300D\u5F71\u5370\u4F5C\u300C\u4E4B\u5019\u300D;\u2461\u300C\u5176\u6027\u81F3\u67D4\u300D\u5F71\u5370\u4F5C\u300C\u96E8\u9732\u4E4B\u6027\u81F3\u5F31\u300D;\u2462\u300C\u8F9B\u4E19\u4E24\u900F\uFF0C\u91D1\u699C\u6709\u540D\u300D\u5F71\u5370\u4F5C\u300C\u5F97\u4E19\u8F9B\u5169\u900F\uFF0C\u79D1\u7532\u5BCC\u8CB4\u975E\u5E38\u300D(\u6863\u540C\u4E3A\u4E0A,\u63AA\u8F9E\u5F02);\u2463\u2605\u5F71\u5370\u300C\u8F9B\u5728\u9149\u4E11\u300D\u660E\u4F5C\u300C\u8F9B\u85CF\u9149\u4E11\u300D\u2014\u2014\u5370\u8BC1\u672C\u8868\u628A\u8BE5\u6761\u5224\u4E3A\u8F9B\u4E0D\u900F\u7684\u505A\u6CD5;\u2464\u2605\u300C\u6216\u8F9B\u900F\u4E19\u85CF\u300D\u5F71\u5370\u4F5C\u300C\u6216\u8F9B\u900F\u58EC\u85CF\u300D,\u6761\u4EF6\u5B57\u4E0D\u540C;\u2465\u2605\u300C\u4E19\u8F9B\u5728\u67F1\uFF0C\u4EE5\u5BCC\u5F97\u5B98\u300D\u5F71\u5370\u4F5C\u300C\u4E19\u8F9B\u7686\u85CF\uFF0C\u5BCC\u4E2D\u53D6\u8CB4\u300D,\u6761\u4EF6\u4E0E\u65AD\u8BED\u4FF1\u5F02\u3002\u4F59\u53E5\u5927\u4F53\u4E00\u81F4(\u53D7\u4F24/\u53D7\u56F0\u3001\u8D2B\u7A77/\u8CA7\u8CE4\u3001\u8863\u887F/\u8CA2\u76E3\u751F\u54E1\u3001\u8D2B\u5BD2\u4E0B\u683C/\u5B9A\u4E3B\u8CA7\u8CE4 \u7686\u540C\u6863\u5F02\u8F9E)\u3002"
      },
      \u4E24\u7CFB\u5206\u6B67: [
        {
          \u6761\u4F8B: "\u7678\u5BC5-\u8F9B\u900F\u4E19\u85CF",
          \u7A77\u901A\u5B9D\u9274\u7CFB: "\u6216\u8F9B\u900F\u4E19\u85CF\uFF0C\u6069\u8363\u4E4B\u9020",
          \u9020\u5316\u5143\u94A5\u7CFB: "\u6216\u8F9B\u900F\u58EC\u85CF\uFF0C\u6069\u5C01\u986F\u8077",
          \u8BF4\u660E: "\u7B2C\u4E8C\u5B57\u77E5\u781A\u658B\u4F5C\u300C\u4E19\u300D\u3001\u5F71\u5370\u672C\u4F5C\u300C\u58EC\u300D,\u662F\u6761\u4EF6\u5B57\u672C\u8EAB\u7684\u5F02\u6587,\u4E0D\u662F\u63AA\u8F9E\u51FA\u5165\u3002\u672C\u8868\u6761\u4F8B\u4E3B\u4F53\u4ECE\u77E5\u781A\u658B\u672C(\u900F:\u8F9B \u4E14 \u975E \u900F:\u4E19);\u82E5\u4ECE\u9020\u5316\u5143\u94A5\u7CFB\u5E94\u4F5C\u300C\u900F:\u8F9B \u4E14 \u975E \u900F:\u58EC\u300D\u3002\u4E24\u7248\u5E76\u5B58,\u4E0D\u64C5\u81EA\u62E9\u4E00\u3002"
        },
        {
          \u6761\u4F8B: "\u7678\u5BC5-\u4E19\u8F9B\u5728\u67F1",
          \u7A77\u901A\u5B9D\u9274\u7CFB: "\u4E19\u8F9B\u5728\u67F1\uFF0C\u4EE5\u5BCC\u5F97\u5B98",
          \u9020\u5316\u5143\u94A5\u7CFB: "\u4E19\u8F9B\u7686\u85CF\uFF0C\u5BCC\u4E2D\u53D6\u8CB4",
          \u8BF4\u660E: "\u77E5\u781A\u658B\u300C\u5728\u67F1\u300D= \u5168\u76D8\u53EF\u89C1,\u5F71\u5370\u300C\u7686\u85CF\u300D= \u4E8C\u5B57\u4FF1\u4E0D\u900F\u3002\u65AD\u8BED\u300C\u4EE5\u5BCC\u5F97\u5B98\u300D\u4E0E\u300C\u5BCC\u4E2D\u53D6\u8CB4\u300D\u540C\u4E3A\u4E2D\u6863\u3002\u26A0\u5BC5\u6708\u6708\u4EE4\u6052\u85CF\u4E19,\u6545\u9020\u5316\u5143\u94A5\u7CFB\u7684\u300C\u4E19\u85CF\u300D\u5728\u672C\u683C\u6052\u771F,\u5176\u6761\u4EF6\u5B9E\u9645\u53EA\u5269\u300C\u8F9B\u85CF\u4E0D\u900F\u300D\u2014\u2014\u53CD\u800C\u6BD4\u77E5\u781A\u658B\u7CFB\u66F4\u6613\u547D\u4E2D\u3002\u672C\u8868\u4ECE\u77E5\u781A\u658B\u7CFB\u3002"
        }
      ],
